r=Path(__file__).resolve().parent;root=r.parent.parent;p=r/'private/native';out=Path.home()/'Videos/Studio - Open Country - Cinematic Edit - 2026-11-08'
def read(f):return json.loads(Path(f).read_text())
def sha(f):return hashlib.sha256(Path(f).read_bytes()).hexdigest()
def copy(a,b):
 a=Path(a);b=Path(b);b.parent.mkdir(parents=True,exist_ok=True)
 if b.exists() and sha(a)!=sha(b):raise RuntimeError('Preserve delivered bytes: '+str(b))
 shutil.copy2(a,b)
